"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"

type Mode = "view" | "edit" | "add"

type StudentFormProps = {
  mode: Mode
  title: string
  defaultData?: any
}

export default function StudentForm({
  mode,
  title,
  defaultData,
}: StudentFormProps) {
  const router = useRouter()

  const isView = mode === "view"

  const [form, setForm] = useState({
    name: defaultData?.name || "",
    admissionNo: defaultData?.admissionNo || "",
    aadhar: defaultData?.aadhar || "",
    classAdmitted: defaultData?.classAdmitted || "",
    photo: defaultData?.photo || "",
    photoFile: null as File | null,
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    if (isView) return

    const payload = new FormData()
    payload.append("name", form.name)
    payload.append("admissionNo", form.admissionNo)
    payload.append("aadhar", form.aadhar)
    payload.append("classAdmitted", form.classAdmitted)

    if (form.photoFile) {
      payload.append("photo", form.photoFile)
    }

    console.log("SUBMIT DATA", payload)
    // 🔥 call your API here
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">{title}</h1>

        <Button
          type="button"
          variant="outline"
          onClick={() => router.back()}
        >
          Back
        </Button>
      </div>

      {/* Card */}
      <div className="rounded-xl border bg-white p-6 space-y-6">
        <h2 className="text-lg font-semibold">Student Details</h2>

        {/* Profile Picture */}
        <div className="flex items-center gap-6">
          <img
            src={form.photo || "/avatar.png"}
            alt="Profile"
            className="h-24 w-24 rounded-lg border object-cover"
          />

          {!isView && (
            <Input
              type="file"
              accept="image/*"
              onChange={(e) =>
                setForm({
                  ...form,
                  photoFile: e.target.files?.[0] || null,
                })
              }
            />
          )}
        </div>

        {/* Fields Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Name */}
          <div>
            <Label>Name Of The Pupil</Label>
            {isView ? (
              <p className="mt-2 text-sm">{form.name || "-"}</p>
            ) : (
              <Input
                value={form.name}
                onChange={(e) =>
                  setForm({ ...form, name: e.target.value })
                }
              />
            )}
          </div>

          {/* Admission No */}
          <div>
            <Label>Admission No</Label>
            {isView ? (
              <p className="mt-2 text-sm">
                {form.admissionNo || "-"}
              </p>
            ) : (
              <Input
                value={form.admissionNo}
                onChange={(e) =>
                  setForm({ ...form, admissionNo: e.target.value })
                }
              />
            )}
          </div>

          {/* Aadhaar */}
          <div>
            <Label>Student Aadhaar No</Label>
            {isView ? (
              <p className="mt-2 text-sm">{form.aadhar || "-"}</p>
            ) : (
              <Input
                value={form.aadhar}
                onChange={(e) =>
                  setForm({ ...form, aadhar: e.target.value })
                }
              />
            )}
          </div>

          {/* Class */}
          <div>
            <Label>Class Admitted</Label>
            {isView ? (
              <p className="mt-2 text-sm">
                {form.classAdmitted || "-"}
              </p>
            ) : (
              <Input
                value={form.classAdmitted}
                onChange={(e) =>
                  setForm({
                    ...form,
                    classAdmitted: e.target.value,
                  })
                }
              />
            )}
          </div>
        </div>

        {/* Footer Buttons */}
        {!isView && (
          <div className="flex justify-end gap-4 pt-4">
            <Button type="submit" className="px-8">
              {mode === "edit" ? "Update Student" : "Add Student"}
            </Button>
          </div>
        )}
      </div>
    </form>
  )
}
